CREATE FUNCTION public.set_accepted_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Če je ticket ustvarjen s stanjem 'open' ali se spremeni iz 'new' v 'open'
    IF NEW.state = 'open' AND (TG_OP = 'INSERT' OR OLD.state = 'new') THEN
        NEW.accepted_at = NOW();
    END IF;
    RETURN NEW;
END;
$$;


