--
-- Name: ticket trg_set_accepted_at_update; Type: TRIGGER; Schema: public; Owner: postgres
--

CREATE TRIGGER trg_set_accepted_at_update BEFORE UPDATE ON public.ticket FOR EACH ROW WHEN ((((new.state)::text = 'open'::text) AND ((old.state)::text = 'new'::text))) EXECUTE FUNCTION public.set_accepted_at();

ALTER TABLE public.ticket DISABLE TRIGGER trg_set_accepted_at_update;


--
-- Name: ticket trg_set_resolved_at; Type: TRIGGER; Schema: public; Owner: postgres
--

CREATE TRIGGER trg_set_resolved_at BEFORE UPDATE ON public.ticket FOR EACH ROW WHEN (((new.state)::text = ANY (ARRAY[('cancelled'::character varying)::text, ('resolved'::character varying)::text, ('closed'::character varying)::text]))) EXECUTE FUNCTION public.set_resolved_at();

ALTER TABLE public.ticket DISABLE TRIGGER trg_set_resolved_at;


